(() => {const systems=[['Grand Closure','grandClosure'],['BPF Observation','bpf'],['Ring Consumer','x2'],['AF_XDP Lab','x3'],['Chunk Transport','x4'],['Transport Economics','x5'],['Cross-node Reconstruction','x6'],['Production NIC Canary','x7'],['PRISM Remote Residual','x8'],['llama.cpp Prompt Cache','llamacpp']];const esc=v=>String(v??'—').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));function renderer(){const root=document.createElement('div');root.className='beast-page beast-reality-page';root.innerHTML=`<header class="beast-page-head"><div><h2>Reality Matrix</h2><div class="sub">DECLARED CAPABILITY VERSUS PHYSICALLY OBSERVED STATE</div></div><div class="beast-page-actions"><button class="beast-button secondary" data-nav="doctor">Open Doctor</button><button class="beast-button hot" data-reality-refresh>Refresh Reality</button></div></header><section class="reality-legend"><span>INSTALLED</span><span>READY</span><span>LIVE</span><span>VERIFIED</span></section><section class="reality-matrix" data-reality-matrix></section>`;const render=state=>{const reality=state.reality||state.system?.reality||{};root.querySelector('[data-reality-matrix]').innerHTML=systems.map(([name,key])=>{const r=reality[key]||{};const levels=[['Installed',r.installed],['Ready',r.ready],['Live',r.live],['Verified',r.verified]];return `<article class="reality-row"><header><b>${name}</b><small>${esc(r.receipt||r.note||'No live receipt projected')}</small></header>${levels.map(([l,v])=>`<div class="reality-cell ${v===true?'yes':v===false?'no':'unknown'}"><span>${l}</span><b>${v===true?'YES':v===false?'NO':'—'}</b></div>`).join('')}</article>`}).join('')};const unsub=BeastStore.subscribe(render);render(BeastStore.get());return{node:root,dispose(){unsub?.();}};}window.BeastRealityPage={renderer};})();
